// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address burner, uint256 burnAmount) public {
        vm.assume(burner != address(0));
        vm.assume(burner != c.owner());
        vm.prank(c.owner());
        c.mintToken(burner, burnAmount + 1);
        vm.deal(burner, 0);
        vm.prank(burner);

        bool ok;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
